harness.driver_c:
#include <klee/klee.h>
#include <stdlib.h>
#include <string.h>

/* Forward declaration of the vulnerable function defined in slice */
void vulnerable(unsigned char *dst, size_t dst_size,
                unsigned char *src, size_t src_size);

int main(void) {
    size_t dst_size;
    size_t src_size;

    klee_make_symbolic(&dst_size, sizeof(dst_size), "dst_size");
    klee_make_symbolic(&src_size, sizeof(src_size), "src_size");

    /* Keep sizes bounded to avoid state explosion */
    klee_assume(dst_size >= 1 && dst_size <= 64);
    klee_assume(src_size >= 1 && src_size <= 128);

    /* Trigger condition: src_size > dst_size causes heap overflow */
    klee_assume(src_size > dst_size);

    unsigned char *dst = calloc(dst_size, 1);
    unsigned char *src = calloc(src_size, 1);

    if (!dst || !src) return 1;

    /* Make source buffer contents symbolic */
    klee_make_symbolic(src, src_size, "src_data");

    /* Call vulnerable: memcpy will write src_size bytes into dst_size buffer */
    vulnerable(dst, dst_size, src, src_size);

    free(dst);
    free(src);
    return 0;
}

harness.slice_c:
#include <stdlib.h>
#include <string.h>
#include <klee/klee.h>

/* ------------------------------------------------------------------ */
/* SPINE_PROBE macro: marks function entry for coverage tracking       */
/* ------------------------------------------------------------------ */
#define SPINE_PROBE(name) klee_assert(1 && name)

/* ------------------------------------------------------------------ */
/* Vulnerable function with sink assertion                             */
/* ------------------------------------------------------------------ */
void vulnerable(unsigned char *dst, size_t dst_size,
                unsigned char *src, size_t src_size) {
    SPINE_PROBE("vulnerable");

    /* Branch stub: no bounds check — this is the bug */
    /* Loop stub: no loop in this function */

    /* CWE-120/CWE-122 sink:
     * memcpy called with src_size not bounded by dst_size.
     * When src_size > dst_size, dst heap buffer is overflowed. */
    memcpy(dst, src, src_size);   /* ← ℓ  line 6 */

    /* Sink reached: trigger KLEE assertion error */
    klee_assert(0 && "SAILOR_SINK_REACHED");
}
